import sympy
from sympy import Poly, Symbol
from sympy.polys.domains import GF

def get_gcd_deg(n):
    x = Symbol('x')
    L_prime = (1 + x) * (1 + (1 + x)**n)
    R_prime = x * (1 + x**n)
    L_poly = Poly(L_prime, x, domain=GF(2))
    R_poly = Poly(R_prime, x, domain=GF(2))
    G_poly = sympy.gcd(L_poly, R_poly)
    return G_poly.degree()

results = []
for n in range(2, 501):
    if get_gcd_deg(n) >= 3:
        results.append(n)

if results:
    print(max(results))
else:
    print(None)

import collections

def solve_small(n):
    moves = []
    for i in range(n - 1):
        for j in range(n - 1):
            m = [0] * (n * n)
            m[i * n + j] = 1
            m[(i + 1) * n + j] = 1
            m[i * n + (j + 1)] = 1
            moves.append(tuple(m))
    for j in range(n):
        m = [0] * (n * n)
        for i in range(n):
            m[i * n + j] = 1
        moves.append(tuple(m))
    for i in range(n):
        m = [0] * (n * n)
        for j in range(n):
            m[i * n + j] = 1
        moves.append(tuple(m))

    l_moves_count = (n - 1)**2

    first_moves = []
    for idx, m in enumerate(moves):
        if idx < l_moves_count:
            first_moves.append(m)

    queue = collections.deque()
    visited = {}

    for m in first_moves:
        if m not in visited:
            visited[m] = 1
            queue.append(m)

    while queue:
        curr = queue.popleft()
        if curr == tuple([0] * (n * n)):
            return True
        if len(visited) > 100000:
            break
        for idx, m in enumerate(moves):
            is_valid = False
            if idx < l_moves_count:
                indices = [i for i, val in enumerate(m) if val == 1]
                if all(curr[i] == 0 for i in indices):
                    is_valid = True
            else:
                indices = [i for i, val in enumerate(m) if val == 1]
                if all(curr[i] == 1 for i in indices):
                    is_valid = True
            if is_valid:
                new_state = tuple(curr[i] ^ m[i] for i in range(n*n))
                if new_state == tuple([0] * (n * n)):
                    return True
                if new_state not in visited:
                    visited[new_state] = visited[curr] + 1
                    queue.append(new_state)
    return False

for n in range(2, 7):
    print(f"n={n}: {solve_small(n)}")
